    {
      "@id": "entity:source-homeschool.intro",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware gives homeschool families a complete learning platform — create activities for any location, track each child\\'s progress against state standards, and generate portfolio reports automatically."
    },
    {
      "@id": "entity:target-homeschool.intro-v1",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware يقدم لأهل التعليم المنزلي نظام تعليم كامل — إنشاء أنشطة لجميع مواقع التعليم، تراك تقديماتهم في التحقق من المعايير الوطنية، وإنشاء تقارير الأسرة بشكل تلقائي.",
      "generated_by": {
        "@id": "activity:translation-homeschool.intro-2026-05-31T18:13:19.575308+00:00"
      },
      "used_source": {
        "@id": "entity:source-homeschool.intro"
      }
    },
